mapper.update:
UPDATE event_user_permissions
SET effect = #{effect}, granted_by = #{grantedBy}, granted_at = #{grantedAt}
WHERE space_id = #{spaceId}
  AND event_id = #{eventId}
  AND user_id = #{userId}
  AND permission = #{permission}

mapper.delete:
DELETE FROM event_user_permissions
WHERE space_id = #{spaceId}
  AND event_id = #{eventId}
  AND user_id = #{userId}
  AND permission = #{permission}
